CREATE VIEW SCHEMA1.VIEW1 AS
SELECT COL1
FROM SCHEMA1.TABLE1;

create view schema1.view2 as
select col1
from schema1.table1
with no row movement;

CREATE VIEW SCHEMA1.VIEW3 AS
SELECT COL1
FROM SCHEMA1.TABLE1
WITH ROW MOVEMENT;

CREATE VIEW SCHEMA1.VIEW4 (COL1) AS
SELECT COL1
FROM SCHEMA1.TABLE1
WITH CHECK OPTION;

CREATE VIEW SCHEMA1.VIEW5 AS
SELECT COL1
FROM SCHEMA1.TABLE1
WITH CASCADED CHECK OPTION;

CREATE VIEW SCHEMA1.VIEW6 AS
SELECT COL1
FROM SCHEMA1.TABLE1
WITH LOCAL CHECK OPTION;

CREATE OR REPLACE VIEW SCHEMA1.VIEW7 AS
SELECT COL1
FROM SCHEMA1.TABLE1
WITH NO ROW MOVEMENT;
